import Foundation
import Testing
@testable import KasumiMarkdown

private struct ProfileMathCase: Decodable {
    let font: MathFontChoice
    let tex: String
    let display: Bool
    let size: Double
    let gap: Double
    let overhang: Double
    let result: Result
    struct Result: Decodable {
        let width: Double
        let ascent: Double
        let descent: Double
        let status: Int
        let glyphs: [Glyph]
        let rules: [Rule]
    }
    struct Glyph: Decodable { let glyph: UInt16; let size: Double; let x: Double; let y: Double; let color: UInt32 }
    struct Rule: Decodable { let x: Double; let y: Double; let width: Double; let height: Double; let color: UInt32 }
}

@Test func profileMathMatchesNativeFontsAndSpacingOptions() throws {
    let cases = try JSONDecoder().decode([ProfileMathCase].self, from: Data(profileMathOracle.utf8))
    for item in cases {
        let options = MathProfileOptions(font: item.font, radicalGap: item.gap, fractionBarOverhang: item.overhang)
        let actual = MathTypesetter.layout(item.tex, size: item.size, display: item.display, options: options)
        let label = "\(item.font), \(item.tex), display=\(item.display), gap=\(item.gap), overhang=\(item.overhang)"
        #expect(abs(actual.box.width - item.result.width) < 0.0001, "\(label) width")
        #expect(abs(actual.box.ascent - item.result.ascent) < 0.0001, "\(label) ascent")
        #expect(abs(actual.box.descent - item.result.descent) < 0.0001, "\(label) descent")
        #expect(actual.diagnostics.isEmpty == (item.result.status == 0), "\(label) glyph availability")
        var glyphs: [ProfileMathCase.Glyph] = [], rules: [ProfileMathCase.Rule] = []
        func collect(_ drawings: [MathDrawing], color: UInt32 = 0) {
            for drawing in drawings {
                switch drawing {
                case let .glyph(font, glyph, point):
                    glyphs.append(.init(glyph: glyph, size: CTFontGetSize(font), x: point.x, y: actual.box.ascent - point.y, color: color))
                case let .rule(rect): rules.append(.init(x: rect.minX, y: actual.box.ascent - rect.maxY, width: rect.width, height: rect.height, color: color))
                case let .colored(rgba, children): collect(children, color: rgba)
                case .text: Issue.record("Unexpected text drawing in native profile oracle")
                }
            }
        }
        collect(actual.box.drawings)
        #expect(glyphs.count == item.result.glyphs.count, "\(label) glyph count")
        #expect(rules.count == item.result.rules.count, "\(label) rule count")
        for expected in item.result.glyphs {
            let found = glyphs.firstIndex { $0.glyph == expected.glyph && abs($0.size - expected.size) < 0.0001 && abs($0.x - expected.x) < 0.0001 && abs($0.y - expected.y) < 0.0001 && $0.color == expected.color }
            #expect(found != nil, "\(label) glyph \(expected.glyph) at (\(expected.x), \(expected.y))")
            if let found { glyphs.remove(at: found) }
        }
        for expected in item.result.rules {
            let found = rules.firstIndex { abs($0.x - expected.x) < 0.0001 && abs($0.y - expected.y) < 0.0001 && abs($0.width - expected.width) < 0.0001 && abs($0.height - expected.height) < 0.0001 && $0.color == expected.color }
            #expect(found != nil, "\(label) rule at (\(expected.x), \(expected.y))")
            if let found { rules.remove(at: found) }
        }
    }
}

@Test func profileMathFontsAreUnmodifiedAndRetainedByEachDrawing() throws {
    let hashes: [MathFontChoice: String] = [
        .newCMRegular: "60394d357348f68cd301764fe61cc502a5858e1c4ff21b948a1d14d82586a7a2",
        .newCMBook: "ac2f4393db81faa7242751483e52de8fd784c89bd00c20d07aaa938c68441ff8",
        .pagellaMath: "1f9e010f60e947d0e925910009b2ea85ad54edc7cefb106f8cdefb9ffd1d5f2f"
    ]
    let retained = MathTypesetter.layout(#"\sqrt{x_i^2}+\frac{1}{2}"#, size: 16, display: true, options: .init(font: .pagellaMath))
    for face in MathFontChoice.allCases {
        let font = try Data(contentsOf: MathFont.resourceURL(for: face))
        #expect(SHA256.hash(data: font).map { String(format: "%02x", $0) }.joined() == hashes[face])
        let layout = MathTypesetter.layout("x_i^2", size: 16, display: true, options: .init(font: face))
        #expect(layout.diagnostics.isEmpty)
    }
    for drawing in retained.box.drawings {
        if case let .glyph(font, _, _) = drawing {
            #expect(CTFontCopyPostScriptName(font) as String == "TeXGyrePagellaMath-Regular")
        }
    }
    #expect(MathFont.metrics(size: 16, face: .pagellaMath).scriptPercentScaleDown == 0.74)
    #expect(MathFont.metrics(size: 16, face: .pagellaMath).scriptScriptPercentScaleDown == 0.55)
}

@Test func profileMathMissingGlyphsFallBackForTheWholeFormula() {
    let missing = MathAttachment(source: "A⫋B", size: 16, display: false, options: .init(font: .pagellaMath))
    #expect(missing.result.diagnostics.contains { $0.contains("U+2ACB") })
    #expect(missing.result.box.drawings.isEmpty)
    #expect(missing.result.box.width == 0)
    #expect(missing.source == "A⫋B")
    let fallbackFont = PlatformFont.monospacedSystemFont(ofSize: 13, weight: .regular)
    let fallback = missing.attributed(color: .black, fallbackFont: fallbackFont)
    #expect(fallback.string == missing.source)
    #expect(fallback.attribute(.kasumiMath, at: 0, effectiveRange: nil) == nil)
    #expect((fallback.attribute(.font, at: 0, effectiveRange: nil) as? PlatformFont) == fallbackFont)
    let map = DocumentTextMap(fallback)
    #expect(map.substring(in: NSRange(location: 0, length: 1)) == "A")
    #expect(map.matches("B") == [NSRange(location: 2, length: 1)])
    for face in [MathFontChoice.newCMRegular, .newCMBook] {
        #expect(MathTypesetter.layout("A⫋B", size: 16, display: false, options: .init(font: face)).diagnostics.isEmpty)
    }
    #expect(MathProfileOptions(radicalGap: .nan, fractionBarOverhang: .infinity) == .init())
}

@Test func profileMathFontChoiceDoesNotLeakAcrossConcurrentDocuments() async {
    await withTaskGroup(of: Bool.self) { group in
        for index in 0..<36 {
            let face = MathFontChoice.allCases[index % MathFontChoice.allCases.count]
            group.addTask {
                let result = MathTypesetter.layout(#"\sqrt{x_i^2}+\frac{1}{2}"#, size: 16, display: true, options: .init(font: face))
                let expected: String
                switch face {
                case .newCMRegular: expected = "NewCMMath-Regular"
                case .newCMBook: expected = "NewCMMath-Book"
                case .pagellaMath: expected = "TeXGyrePagellaMath-Regular"
                }
                return result.diagnostics.isEmpty && result.box.drawings.allSatisfy {
                    if case let .glyph(font, _, _) = $0 { return CTFontCopyPostScriptName(font) as String == expected }
                    return true
                }
            }
        }
        for await matches in group { #expect(matches) }
    }
}

